  rw_cells asegs mx (spa + 24) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -128 - spa -> spa <= bv_unsigned sp + -128 -> bv_unsigned sp + -144 <= spa -> spa mod 16 = 0 ->
  rw_cells asegs mx (bv_unsigned sp + -104) (sd_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells asegs mx fp [C1 bflag] ->
  stk asegs mx lo spa -> mem_inv asegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi -> as_RFS H LF m ->
